#include <bits/stdc++.h>using namespace std;#define int long long#define go(i,a,b) for(int i=a;i<=b;i++)#define og(i,a,b) for(int i=b;i>=a;i--)#define all() a.begin() + 1,a.begin() + n + 1int T,n; void O_o(){    cin >> n;    vector<int> a(n + 1);    for(int i=1;i<=n;i++){        cin >> a[i];    }    if(n == 1){        cout << a[0] << '\n';        return ;    }else if(n == 2){        cout << min(a[0],a[1]) << '\n';        return ;    }    int mx = -1,p = -1;    mx = abs(a[1] - a[2]);    p = 1;    if(abs(a[n - 1] - a[n]) > mx){        mx = abs(a[n - 1] - a[n]);        p = n;    }    for(int i=2;i<=n - 1;i++){        int x = a[i - 1],y = a[i],z = a[i + 1];        if(abs(x - y) + abs(y - z) - abs(x - z) > mx){            mx = abs(x - y) + abs(y - z) - abs(x - z);            p = i;        }    }    int ans = 0;    for(int i=2;i<=n;i++){        ans += abs(a[i] - a[i - 1]);    }    cout << ans - mx << '\n';} signed main(){    ios::sync_with_stdio(false);    cin.tie(nullptr);cout.tie(nullptr);    cin >> T;    while(T--)O_o();}